#include "RecordReferences/MaterialRecordReference.h"
#include "RecordDefinitions/MaterialRecord.h"
#include "ArgusLogging.h"

#if WITH_EDITOR && WITH_EDITORONLY_DATA
void FUMaterialRecordReference::StoreId() const
{
	if (m_softObjectPtr.IsNull())
	{
		m_id = 0;
		return;
	}

	if (const UMaterialRecord* record = m_softObjectPtr.LoadSynchronous())
	{
		m_id = record->m_id;
	}
	else
	{
		ARGUS_ERROR_NULL(ArgusStaticDataLog, record);
	}
}

void FUMaterialRecordReference::CacheRecordAsReference(UMaterialRecord* record)
{
	ARGUS_RETURN_ON_NULL(record, ArgusStaticDataLog);
	m_softObjectPtr = TSoftObjectPtr<UMaterialRecord>(record);
	StoreId();
}
#endif
